svg.script:
var skaterPos = document.getElementById('skaterPos');
var skaterRot = document.getElementById('skaterRot');
var riderStand = document.getElementById('riderStand');
var riderTuck = document.getElementById('riderTuck');
var shadow = document.getElementById('shadow');
var trail = document.getElementById('trail');
var trickLabel = document.getElementById('trickLabel');

// Physics constants
var G = 900; // px/s^2
var VX = 250; // horizontal speed px/s
var JUMP_SPEED = 700; // upward launch speed
var JUMP_X = 300; // takeoff x
var GROUND_Y = 450;
var BOARD_Y = GROUND_Y - 11;
var RESET_X = 850;
var START_X = 50;

var state = 'ground';
var x = START_X;
var y = BOARD_Y;
var vy = 0;
var flightTime = 0;
var totalFlightTime = 2 * JUMP_SPEED / G;
var rot = 0;
var lastTime = null;

// Precompute the theoretical jump curve for display
var d = 'M' + JUMP_X + ' ' + BOARD_Y;
for (var i = 0; i <= 40; i++) {
  var t = (i / 40) * totalFlightTime;
  var px = JUMP_X + VX * t;
  var py = BOARD_Y - JUMP_SPEED * t + 0.5 * G * t * t;
  d += ' L' + px.toFixed(1) + ' ' + py.toFixed(1);
}
trail.setAttribute('d', d);

function setPose(tuck) {
  if (tuck) {
    riderStand.style.display = 'none';
    riderTuck.style.display = '';
  } else {
    riderStand.style.display = '';
    riderTuck.style.display = 'none';
  }
}

function updateDisplay() {
  skaterPos.setAttribute('transform', 'translate(' + x.toFixed(1) + ',' + y.toFixed(1) + ')');
  skaterRot.setAttribute('transform', 'rotate(' + rot.toFixed(1) + ', 0, -40)');

  var height = BOARD_Y - y;
  if (height < 0) height = 0;
  var opac = Math.max(0.1, 0.35 - height / 400);
  shadow.setAttribute('opacity', opac.toFixed(2));
  shadow.setAttribute('rx', (20 - Math.min(15, height / 20)).toFixed(1));
  shadow.setAttribute('cx', x.toFixed(1));

  if (state === 'air') {
    trickLabel.setAttribute('opacity', Math.min(1, (flightTime / 0.3) * 0.9).toFixed(2));
  } else {
    trickLabel.setAttribute('opacity', '0');
  }
}

function reset() {
  x = START_X;
  y = BOARD_Y;
  vy = 0;
  state = 'ground';
  rot = 0;
  setPose(false);
}

function animate(time) {
  if (lastTime === null) lastTime = time;
  var dt = (time - lastTime) / 1000;
  lastTime = time;
  if (dt > 0.05) dt = 0.05;

  if (state === 'ground') {
    x += VX * dt;
    if (x >= JUMP_X) {
      x = JUMP_X;
      state = 'air';
      vy = -JUMP_SPEED;
      flightTime = 0;
      setPose(true);
    }
    if (x >= RESET_X) {
      reset();
    }
  } else if (state === 'air') {
    flightTime += dt;
    x += VX * dt;
    vy += G * dt;
    y += vy * dt;
    rot = (flightTime / totalFlightTime) * 360;

    if (y >= BOARD_Y) {
      y = BOARD_Y;
      vy = 0;
      state = 'ground';
      rot = 0;
      setPose(false);
    }
  }

  updateDisplay();
  requestAnimationFrame(animate);
}

setPose(false);
updateDisplay();
requestAnimationFrame(animate);
